"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3227],{43557:e=>{e.exports=JSON.parse('{"functions":[{"name":"scope","desc":"Runs `callback` inside a MicroProfiler scope named `label` and returns whatever it\\nreturns. The scope is always closed, and an error thrown by `callback` is\\nre-raised after it closes.\\n\\nOnly use this for synchronous code: `callback` must not yield.\\n\\n```lua\\nlocal path = ProfileUtil.scope(\\"ComputePath\\", function()\\n\\treturn computePath(start, goal)\\nend)\\n```","params":[{"name":"label","desc":"The name shown in the MicroProfiler.","lua_type":"string"},{"name":"callback","desc":"A function that does not yield.","lua_type":"() -> T..."}],"returns":[{"desc":"The values returned by `callback`.","lua_type":"T..."}],"function_type":"static","source":{"line":28,"path":"src/ProfileUtil.luau"}}],"properties":[],"types":[],"name":"ProfileUtil","desc":"Helpers for labelling code in the MicroProfiler.","source":{"line":7,"path":"src/ProfileUtil.luau"}}')}}]);